1	package com.example.starter.firmware.service;
2	
3	import com.example.starter.firmware.api.CreateReleaseRequest;
4	import com.example.starter.firmware.api.ExpandReleaseRequest;
5	import com.example.starter.firmware.api.MonitorView;
6	import com.example.starter.firmware.api.PauseRecordView;
7	import com.example.starter.firmware.api.ReleaseHistoryResponse;
8	import com.example.starter.firmware.api.ReleaseView;
9	import com.example.starter.firmware.api.ResumeRecordView;
10	import com.example.starter.firmware.api.ResumeReleaseRequest;
11	import com.example.starter.firmware.domain.ReleaseOrder;
12	import com.example.starter.firmware.domain.ReleaseStatus;
13	import com.example.starter.firmware.error.ApiException;
14	import com.example.starter.firmware.repo.PauseRecordRepository;
15	import com.example.starter.firmware.repo.ReleaseRepository;
16	import com.example.starter.firmware.repo.ResumeRecordRepository;
17	import com.example.starter.firmware.repo.TaskRepository;
18	import org.springframework.dao.DuplicateKeyException;
19	import org.springframework.stereotype.Service;
20	
21	import java.time.Clock;
22	import java.time.Instant;
23	
24	/**
25	 * 发布单生命周期：创建（版本从1开始）、扩量（版本校验+只增不减）、失败率自动暂停、
26	 * 人工恢复（版本加一并开启新监控轮次）、取消（未终结任务转 CANCELLED）。
27	 */
28	@Service
29	public class ReleaseService {
30	
31	    private final ReleaseRepository releaseRepository;
32	    private final TaskRepository taskRepository;
33	    private final PauseRecordRepository pauseRecordRepository;
34	    private final ResumeRecordRepository resumeRecordRepository;
35	    private final IdempotencyService idempotency;
36	    private final Clock clock;
37	
38	    public ReleaseService(ReleaseRepository releaseRepository, TaskRepository taskRepository,
39	                          PauseRecordRepository pauseRecordRepository,
40	                          ResumeRecordRepository resumeRecordRepository,
41	                          IdempotencyService idempotency, Clock clock) {
42	        this.releaseRepository = releaseRepository;
43	        this.taskRepository = taskRepository;
44	        this.pauseRecordRepository = pauseRecordRepository;
45	        this.resumeRecordRepository = resumeRecordRepository;
46	        this.idempotency = idempotency;
47	        this.clock = clock;
48	    }
49	
50	    public ReleaseView create(CreateReleaseRequest request) {
51	        if (request.fromVersion().equals(request.toVersion())) {
52	            throw ApiException.badRequest("SAME_VERSION", "目标版本必须与来源版本不同");
53	        }
54	        int sampleFloor = request.effectiveSampleFloor();
55	        int threshold = request.effectiveFailureThresholdPercent();
56	        String fingerprint = String.join("|", "release.create", request.model(), request.fromVersion(),
57	                request.toVersion(), String.valueOf(request.ratio()), String.valueOf(sampleFloor),
58	                String.valueOf(threshold));
59	        return idempotency.execute(request.requestId(), "release.create", fingerprint, () -> {
60	            long id;
61	            try {
62	                id = releaseRepository.insert(request.model(), request.fromVersion(), request.toVersion(),
63	                        request.ratio(), sampleFloor, threshold);
64	            } catch (DuplicateKeyException e) {
65	                throw ApiException.conflict("ACTIVE_RELEASE_EXISTS", "型号已存在未终结发布单: " + request.model());
66	            }
67	            return ReleaseView.of(findOrder(id));
68	        }, ReleaseView.class);
69	    }
70	
71	    public ReleaseView expand(long releaseId, ExpandReleaseRequest request) {
72	        String fingerprint = String.join("|", "release.expand", String.valueOf(releaseId),
73	                String.valueOf(request.expectedVersion()), String.valueOf(request.ratio()));
74	        return idempotency.execute(request.requestId(), "release.expand", fingerprint, () -> {
75	            ReleaseOrder order = releaseRepository.findByIdForUpdate(releaseId)
76	                    .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在: " + releaseId));
77	            if (order.status() != ReleaseStatus.ACTIVE) {
78	                throw ApiException.conflict("RELEASE_NOT_ACTIVE",
79	                        "发布单状态为 " + order.status() + "，不能扩量");
80	            }
81	            if (order.version() != request.expectedVersion()) {
82	                throw ApiException.conflict("VERSION_CONFLICT",
83	                        "expectedVersion 与当前版本不一致: " + order.version());
84	            }
85	            if (request.ratio() < order.ratio()) {
86	                throw ApiException.conflict("RATIO_DECREASE", "投放比例只增不减，当前: " + order.ratio());
87	            }
88	            releaseRepository.expand(releaseId, request.expectedVersion(), request.ratio());
89	            return ReleaseView.of(findOrder(releaseId));
90	        }, ReleaseView.class);
91	    }
92	
93	    /**
94	     * 人工恢复：仅 PAUSED 可恢复为 ACTIVE；版本加一、开启新监控轮次、本轮统计清零。
95	     * 与取消并发时按行锁提交顺序决定唯一结果：取消先提交则恢复 409。
96	     */
97	    public ReleaseView resume(long releaseId, ResumeReleaseRequest request) {
98	        String fingerprint = String.join("|", "release.resume", String.valueOf(releaseId),
99	                String.valueOf(request.expectedVersion()), request.reason());
100	        return idempotency.execute(request.requestId(), "release.resume", fingerprint, () -> {
101	            ReleaseOrder order = releaseRepository.findByIdForUpdate(releaseId)
102	                    .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在: " + releaseId));
103	            if (order.status() == ReleaseStatus.CANCELLED) {
104	                throw ApiException.conflict("RELEASE_CANCELLED", "发布单已取消，不能恢复");
105	            }
106	            if (order.status() != ReleaseStatus.PAUSED) {
107	                throw ApiException.conflict("RELEASE_NOT_PAUSED",
108	                        "发布单状态为 " + order.status() + "，仅 PAUSED 可恢复");
109	            }
110	            if (order.version() != request.expectedVersion()) {
111	                throw ApiException.conflict("VERSION_CONFLICT",
112	                        "expectedVersion 与当前版本不一致: " + order.version());
113	            }
