84	    /**
85	     * 闩锁对齐后并发执行，收集成功结果与异常。
86	     */
87	    private <T> List<Object> runConcurrently(List<Callable<T>> tasks) throws Exception {
88	        CountDownLatch ready = new CountDownLatch(tasks.size());
89	        CountDownLatch start = new CountDownLatch(1);
90	        List<Future<Object>> futures = new ArrayList<>();
91	        for (Callable<T> task : tasks) {
92	            futures.add(executor.submit(() -> {
93	                ready.countDown();
94	                start.await(5, TimeUnit.SECONDS);
95	                try {
96	                    return task.call();
97	                } catch (Exception e) {
98	                    return e;
99	                }
100	            }));
101	        }
102	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
103	        start.countDown();
104	        List<Object> results = new ArrayList<>();
105	        for (Future<Object> future : futures) {
106	            results.add(future.get(30, TimeUnit.SECONDS));
107	        }
108	        return results;
109	    }
