111	    @Test
112	    void 并发拉取_同设备同发布单最多一条任务() throws Exception {
113	        deviceService.register(new RegisterDeviceRequest("req-d", "d1", "m1", "1.0.0", 5));
114	        long releaseId = releaseService.create(new CreateReleaseRequest("req-r", "m1", "1.0.0", "2.0.0", 100))
115	                .releaseId();
116	
117	        int threads = 8;
118	        List<Callable<PullResponse>> tasks = new ArrayList<>();
119	        for (int i = 0; i < threads; i++) {
120	            int seq = i;
121	            tasks.add(() -> taskService.pull("d1", "req-pull-" + seq));
122	        }
123	        List<Object> results = runConcurrently(tasks);
124	
125	        List<Long> taskIds = new ArrayList<>();
126	        for (Object result : results) {
127	            assertThat(result).isInstanceOf(PullResponse.class);
128	            PullResponse response = (PullResponse) result;
129	            assertThat(response.task()).isNotNull();
130	            taskIds.add(response.task().taskId());
131	        }
132	        assertThat(taskIds).allMatch(id -> id.equals(taskIds.get(0)));
133	        assertThat(taskRepository.countByReleaseAndDevice(releaseId, "d1")).isEqualTo(1);
134	    }
