        // 组设备 D1：普通 SUCCESS 回执被屏障拒绝，任务与版本不变
        MvcResult pull1 = mockMvc.perform(post("/api/devices/D1/pull").contentType("application/json")
                .content("{\"requestId\":\"pl1\"}")).andReturn();
